"""Assemble the measured browser report from JSON evidence. Run after the README workflow."""
import hashlib,json
from pathlib import Path
runtime=Path(__file__).resolve().parents[2]
root=runtime/'artifacts'/'browser-test'
repo=runtime.parent.parent
read=lambda name:json.loads((root/name).read_text())
fmt=lambda x,n=3:f'{x:.{n}f}'
parts=[]
def p(s=''):parts.append(s+'\n')
def table(headers,rows):
    p('| '+' | '.join(headers)+' |');p('| '+' | '.join('---' for _ in headers)+' |')
    for row in rows:p('| '+' | '.join(str(v) for v in row)+' |')
    p()
sources=['page-webgpu-local.json','page-wasm-local.json','page-webgpu-hf.json','page-wasm-hf.json','page-webgpu-folder.json','page-webgpu-hf-adventure.json','page-wasm-hf-adventure.json']
matrices={f:read(f) for f in sources}
runs=[r for d in matrices.values() for r in d['runs']]
assert len(runs)==34 and all(not r.get('error') and not r.get('validation') for r in runs)
assert all(all(r['archive'][k] for k in ['audioExact','osuExact','receiptExact']) for r in runs)
assert all(r['detail']['export']['replay_finalized'] for r in runs)
assert all(r['detail']['fallback_count']==0 for r in runs)
placement=read('operator-placement.json')
network=read('diagnostics-webgpu-networks.json')[-1]
compare=next(r for r in read('diagnostics-webgpu-compare.json') if r['type']=='compare-result')
replay={r['song']:r for r in read('diagnostics-wasm-replay.json') if 'song' in r}
control={r['song']:r for r in read('diagnostics-wasm-control.json') if 'song' in r}
assert len(control)==4 and all(r['objectsEqual'] and not r['choiceDifferences'] and r['drawsConsumed']==r['drawsExpected'] for r in control.values())
player=read('player-extended.json')
mobile=read('mobile-contrast.json')
hero=read('hero-contrast.json')
label={'hesitation-snow':'Hesitation Snow','saigetsu':'SaiGetsu','catch-the-moment':'Catch the Moment','adventure':'Adventure'}
order=list(label)
hashes=read('source-hashes.json')
changed=[name for name,sha in hashes.items() if hashlib.sha256((repo/name).read_bytes()).hexdigest()!=sha]
(root/'source-verification.json').write_text(json.dumps({'changed_since_snapshot':changed,'files':len(hashes)},indent=2)+'\n')
assert not changed
p('**Ensomi R2 browser test — 2026-10-11, bings-mac.**')
p('The generator works in headed Chrome on this Apple M5. All four songs pass the requested chart and download checks on WebGPU and forced WASM. Browser-decoded audio does **not** preserve Python replay parity; Catch the Moment exceeds a 1 ms grid-difference target. There are also a GPU-failure recovery defect, a mobile text-contrast failure, a broken runtime link, and horizontal scrolling inside the mobile command example. Product source was not changed.')
p('Environment: macOS 27.0 (26A428), Apple M5, 24 GiB RAM, Chrome 154.0.8037.99, Playwright 1.54.2, ONNX Runtime Web 1.23.2. The first local WebGPU baseline used Chrome 154.0.8037.58 before Chrome updated; the subsequent .99 Hugging Face/folder runs reproduced its charts. Adapter: `apple / metal-3`; no software-GPU or WebGPU-enabling flags. Inference runs in the production Web Worker; WASM uses one thread. Mobile results are Chrome device emulation, not real Safari/Android-device tests.')
p('`npm run build:site` and `npm run typecheck:site` passed. The product was served at `http://127.0.0.1:8087/` because 8080 was occupied. The mac has stale Git metadata (`astra-draft-init`), as expected for this synced workspace; no branch operation, commit, push, or deployment was performed. Tested source/bundle identities are in [source-hashes.json](source-hashes.json); [source-verification.json](source-verification.json) confirms the snapshot stayed unchanged. Generated bundles were rebuilt with the requested build command.')
p('**1. WebGPU execution and numerical agreement.**')
p('All six graphs execute GPU compute dispatches and all six also contain CPU/WASM placements. No real graph/session failure occurred on this Mac. The table combines ORT’s verbose optimized-node placement log, actual `GPUComputePassEncoder.dispatchWorkgroups` observations for one recorded invocation per graph, and a separate complete Catch the Moment generation that ran every graph call twice with identical inputs (WebGPU versus WASM). Placement counts include metadata and copy nodes; they are not shader counts.')
table(['Graph','GPU / CPU nodes','GPU dispatches, one call','Paired calls, song','Maximum absolute output difference'],[[g,f"{placement[g]['WebGpuExecutionProvider']['count']} / {placement[g]['CPUExecutionProvider']['count']}",network['gpuWork'][g]['dispatchWorkgroups'],compare['stats'][g]['calls'],f"{compare['stats'][g]['max']:.9g}"] for g in ['beatthis','rows_encoder','rows_step','r2_predict','r2_release','r2_commit']])
p('The largest WebGPU–WASM difference is **0.0001859665** in BeatThis, over **2,712 paired graph calls**. There were no unequal nonfinite outputs. Every WebGPU/WASM seed-0 hit object and chart duration is identical across the four songs. The largest timing-point value difference is **1.454754965e-7 ms**, below the agreed 1e-6 ms tolerance.')
p('CPU placements: BeatThis has 614 nodes, predominantly int64 shape/index processing (`Gather`, `Unsqueeze`, `Concat`, integer arithmetic and slicing). Rows encoder has 89 shape, index, range and mask nodes. R2 commit’s `/Add_24` updates an int64 counter. R2 predict places `/Cast`, `/ReduceSum`, `/Greater` on CPU; release places 11 nodes from its int64 action/index/count branch on CPU. Rows step places `/gru/GRU`, `/Unsqueeze_2`, and `/LogSoftmax` on CPU; GRU and LogSoftmax are absent from the installed WebGPU operator registry. ORT explicitly logs that some shape-related CPU paths avoid GPU transfer overhead. [operator-placement.json](operator-placement.json) lists **every** placed node, operator, and available inferred dtype. Full logs and direct dispatch evidence are under `bulk/diagnostics-webgpu-networks-*`; full output-error aggregation is in [diagnostics-webgpu-compare.json](diagnostics-webgpu-compare.json).')
p('A missing adapter correctly selects WASM. A separately injected `GPUAdapter.requestDevice` failure leaves the model unloaded with `Could not load the model: 9392000`; it does not retry WASM. This is fault-injection evidence, not a spontaneous failure of this Mac’s GPU. See defect D2 and [fallback.json](fallback.json).')
p('**2. Functional checks.**')
p('There were **34 successful page generations**: four songs through the local HTTP model, Hugging Face, and the directory-upload input (the `onnx/` subfolder), plus provider/cache/section repetitions. Both providers were exercised with local HTTP and Hugging Face; Directory-upload runs used WebGPU. Seed was 0 and stars were the release values below. Every run had integer milliseconds in range, lanes 0–3, start/lane ordering, no duplicate heads or overlapping holds, and all holds closed. Emergency sampling fallback count was zero.')
rows=[]
base=matrices['page-webgpu-local.json']
for song in order:
    r=next(r for r in base['runs'] if r['song']==song and not r['warm'] and not r['section'])
    chart=read(f'bulk/webgpu-local-cold-{song}-chart.json');holds=sum('end_ms' in o for o in chart['objects'])
    rows.append([label[song],r['star'],fmt(chart['duration_ms']/1000,3),len(chart['objects'])-holds,holds,len(chart['objects']),'PASS'])
table(['Song','Stars','Duration, s','Taps','Holds','Total objects','Rules / exports'],rows)
p('Both download links were clicked on every run. All **34 `.osz` files** contain `generated.osu`, the correct `audio.mp3` or `audio.ogg`, and `receipt.json`. Encoded audio is byte-identical to the uploaded file; the archived chart matches the direct `.osu` download and its parsed objects match the result chart. An independent Python ZIP reader verified all CRCs: **34/34 pass**. Evidence: [download-validation.json](download-validation.json), `page-*.json`, and the downloaded files in `bulk/`.')
s=next(r for r in base['runs'] if r['section'])['detail']['controls']['sections'][0]
p(f"SaiGetsu’s requested **20–40 s jumpstream span at 0.7** was accepted on both providers, added bookmarks at 20000/40000 ms, and affected the chart. Its measured stream statistic was **{s['achieved']:.6f}** against target **{s['target']:.6f}**, with jump share **{s['chord_achieved']:.6f}**; both were inside their calibrated bands. A **20–25 s** span displayed `Section 1: a section must last 8–32 seconds.` and disabled Generate before any request was sent. Screenshots: [accepted section](screenshots/webgpu-local-cold-saigetsu-section.png), [invalid section](screenshots/webgpu-invalid-section.png).")
p('**3. Player and Beatmap Lens comparison.**')
p('The instrumented production canvas was checked against `HTMLAudioElement.currentTime`. Note coordinates and the displayed clock were observed independently; the clock has 1 ms display precision. The extended run reused the exact previously generated Adventure chart and original audio to isolate rendering; an earlier freshly generated Adventure result also passed. Each rate was exercised for 60 seconds of wall playback at 240 px/s.')
rows=[]
for rate in ['1','0.5','1.5']:
    r=player['playback'][rate];samples=read(f'bulk/player-{rate}-frames.json');clock_errors=[]
    for sample in samples:
        m,s=sample['clock'].split(' /')[0].split(':');clock_errors.append(abs((int(m)*60+float(s))*1000-sample['audio']))
    rows.append([rate,r['samples'],fmt(r['fps'],3),fmt(r['intervalP95'],2),fmt(r['intervalMax'],2),fmt(r['drawTimeP95'],2),fmt(r['maxDriftMs'],3),fmt(max(clock_errors),3)])
table(['Rate','Frames','FPS','p95 interval, ms','Max interval, ms','p95 draw CPU, ms','Max geometry drift, ms','Max clock-label drift, ms'],rows)
p('There was no accumulated drift and no drift beyond one frame. This measures the browser audio clock and rendered geometry, not acoustic output latency or physical display scanout. Space play/pause, ±5 s keys, ±40 px Up/Down, click seek, drag scrub, wheel, overview seek, and restart passed. Seek errors were at most **0.001 ms** after settling. A macOS/Chrome input scaling detail is documented in [wheel.json](wheel.json): Playwright’s `wheel(0,120)` delivers `deltaY=240`, correctly moving 1000 ms at 240 px/s; a DOM event with `deltaY=120` moves 500 ms. This is not an application wheel defect. Evidence: [player-extended.json](player-extended.json), `bulk/player-*-frames.json`, [player screenshot](screenshots/player-adventure.png).')
p('The named reference `beatmap-lens/apps/inspector/src/InspectWorkspace.vue` currently renders a static SVG preview. The live behavior was compared by source review with `FallingNoteViewport.vue`, `CompareWorkspace.vue`, and the annotation playback controllers; the reference app was not run. Ensomi matches the wheel/arrow direction and pixel-to-time conversion, separates visual speed from audio rate, uses an audio-clock playhead, and supplies a density overview. Gaps: Lens has selection playback/looping, audio offset and volume, and range selection with Shift-drag scrubbing; Ensomi’s plain drag scrubs and has no selection, loop, offset, volume, or arbitrary visual-speed field. These are feature gaps, not failures of the tested transport controls.')
p('**4. Time to first chart.**')
p('Seconds below are individual sequential observations. Cold means a fresh Chrome context with an empty Cache API; warm means a reload after generation populated the cache. OS filesystem, GPU-driver, and CDN-edge caches were not purged. Network timings vary between runs. The two songs are each the **first generation in their session** in this table. Total is model load + browser audio decode + observed Generate-click-to-result wall time, excluding human file-picking time. Decode is read from the page’s 0.01 s timing table; totals are consequently approximate.')
first=[]
for song in ['catch-the-moment','adventure']:
    for backend in ['webgpu','wasm']:
        filename=f'page-{backend}-hf'+('-adventure' if song=='adventure' else '')+'.json';d=matrices[filename]
        for warm in [False,True]:
            r=next(r for r in d['runs'] if r['song']==song and r['warm']==warm);load=next(l for l in d['loads'] if l['warm']==warm);load_s=next(e['seconds'] for e in load['events'] if e['type']=='loaded');decode=float(next(t for t in r['table'] if t.startswith('Audio decode')).split('\t')[1].split()[0]);first.append((song,backend,warm,r,load_s,decode))
table(['Song','Provider','Cache','Model load','Decode','Generation wall','First-chart total'],[[label[song],backend,'warm' if warm else 'cold',fmt(load_s,2),fmt(decode,2),fmt(r['wallSeconds'],2),fmt(load_s+decode+r['wallSeconds'],2)] for song,backend,warm,r,load_s,decode in first])
p('Per-phase receipt timings (s) follow. Cold first-generation frontend and R2 times include deferred downloads of Mel filters and initial-state arrays; they are not pure compute measurements. Receipt generation totals exclude some validation, ZIP packaging and message delivery, so the wall column above is slightly larger.')
for song in ['catch-the-moment','adventure']:
    p(f"{label[song]}:")
    keys=['pcm','spectrogram','beatthis','mel','grid','rows','prior','arrangement','export']
    table(['Provider / cache','PCM','Spectrogram','BeatThis','Mel','Grid','Rows','Prior','R2','Export'],[[backend+(' / warm' if warm else ' / cold')]+[fmt(r['detail']['seconds'][k],3) for k in keys] for s,backend,warm,r,_,_ in first if s==song])
p('An additional test-only worker build timed the production file-reading and session-creation calls separately. It loaded **110,884,603 bytes** (runtime manifest plus six graphs). File read time includes transfer/cache reads and cache writes. Session initialization includes ORT bootstrap/WASM fetching; ORT module import was 0.002–0.003 s. The remaining small difference is manifest parsing and orchestration. These independent load measurements should not be substituted into the first-chart samples above.')
table(['Source','Provider','Cache','File reads / download, s','Graph initialization, s','Total load, s'],[[r['source'],r['backend'],'warm' if r['warm'] else 'cold',fmt(r['readSeconds']),fmt(r['initSeconds']),fmt(r['loadSeconds'])] for r in read('load-benchmark.json')])
p('Warm load-only file reads were all Cache API hits. First generation reads 14 additional filter/state files (1,040,136 bytes), for 111,924,739 model bytes in total; these are cached on first use. See [load-benchmark.json](load-benchmark.json) for individual graph/read times and resource timings. Local compute baselines illustrate the tradeoff: Adventure’s BeatThis takes **1.58 s WebGPU / 19.62 s WASM**, while R2 takes **15.15 / 3.67 s**. Consider choosing providers per graph after fixing frontend parity.')
p('Peak observed renderer RSS in the isolated Adventure cold/warm sessions: **2.83 GiB WebGPU**, **3.15 GiB WASM**; the four-song WASM session reached **3.31 GiB** in the RSS sampler. The page’s main-thread JS heap peaked around **118 MB**, which excludes much worker/WASM/GPU storage. RSS was sampled once per second and includes the whole renderer, retained test results, and decoded audio; GPU allocation peak was not available. Per-session memory fields are in `page-*.json` and the independent samples in `memory-*.json`.')
p('**5. Browser decode against Python.**')
p('The grid comparison evaluates the same 24 candidate head positions per beat as the existing runtime parity check, before whole-ms rounding. Counts and beat indexing matched on all four songs. Pairing differently generated final heads by ordinal would be misleading, so the table uses aligned grid positions instead. Runtime replay used the recorded random values without substituting recorded choices.')
table(['Song','Candidate positions','Max grid difference, ms','Median, ms','Rounded positions changed','First sampled-choice divergence'],[[label[s],replay[s]['traces']['grid']['length'],fmt(replay[s]['traces']['grid']['max'],6),fmt(replay[s]['traces']['grid']['median'],6),replay[s]['traces']['grid']['wholeMsMismatches'],replay[s]['choiceDifferences'][0]['name']] for s in order])
p('None of the browser-PCM replays matches Python. SaiGetsu finishes with **1,203 objects versus 1,215**, and leaves two recorded draws unused; its rows have the same count but some head times differ by 1 ms. The other three change row/hold choices and then cannot consume the original linear draw sequence (the requested draw name no longer matches). Those runs are reported as divergent/aborted, not as completed charts. Full differences and stopping points: [diagnostics-wasm-replay.json](diagnostics-wasm-replay.json).')
p('Positive control: the **same browser WASM runtime and replay harness**, given recorded Python native PCM plus its Mel PCM, reproduces **all 6,178 hit objects and 12,733 choices** exactly across the four songs, consuming every draw. This isolates the failed replay to the browser audio frontend rather than the replay implementation. Evidence: [diagnostics-wasm-control.json](diagnostics-wasm-control.json).')
pcm={r['song']:r for r in read('diagnostics-wasm-pcm.json')}
table(['Song','Native-rate frames difference','24 kHz frames difference','Sampled native PCM max error','Sampled Mel PCM max error'],[[label[s],pcm[s]['browserNativeFrames']-pcm[s]['meta']['frames'],pcm[s]['browserMelFrames']-pcm[s]['meta']['melFrames'],f"{max(w['max'] for w in pcm[s]['windows'] if w['kind']=='native'):.9g}",fmt(max(w['max'] for w in pcm[s]['windows'] if w['kind']=='mel'),6)] for s in order])
p('PCM error samples cover four 2-second windows per song (0, 30, 60, 100 s), not every sample. Native-rate decoding has zero length difference and zero measured lag. Three songs agree within 9e-7 in the sampled native PCM. SaiGetsu has **decoder clipping**: at **30,813.696 ms**, a Python channel value **1.141288161** becomes **1.0** in Chrome, producing a 0.070644 mono difference. This also occurs at negative peaks.')
p('The dominant frontend change is **resampling and amplitude preprocessing**: `src/decode_audio.ts` asks WebAudio to resample independently to 24,000 and 22,050 Hz and then normalizes the Mel stream. Python’s Mel loader uses pydub/ffmpeg, integer audio operations and `set_frame_rate`; BeatThis uses libsndfile plus the recorded torchaudio resampler. Native PCM is nearly identical for the other three songs, while sampled normalized Mel errors reach 0.18–0.38, supporting this attribution. Chrome’s resampled 24 kHz stream is one sample shorter on three songs (**0.041667 ms**); the song-duration difference is at most **0.031462 ms**. Length rounding alone cannot explain Catch the Moment’s 2.67 ms grid change. Both MP3 header classes in these fixtures require zero Python lead correction. Evidence: [diagnostics-wasm-pcm.json](diagnostics-wasm-pcm.json). The exact share of grid error attributable to each resampler was not separately ablated.')
p('**Mobile, theme and contrast.**')
p('The hero, prose, captions, links and previews fit the tested widths; the generator and inspector are hidden and the short desktop-only note is visible. All preview images load. Captions and overall patterns are readable; tiny embedded timing labels remain full-song overview details. There is no page-wide horizontal overflow, but the command example has its own horizontal scrollbar.')
table(['Profile / width','Document scroll width','Tool hidden / note shown','Code box / contents width'],[[r['name']+' / '+str(r['viewport']),r['scrollWidth'],'yes / yes' if not r['toolVisible'] and r['note'] else 'desktop tool visible',str(r['horizontalScrollers'][0]['clientWidth'])+' / '+str(r['horizontalScrollers'][0]['scrollWidth']) if r['horizontalScrollers'] else 'no internal overflow'] for r in mobile])
p('The plum surfaces and lavender/rose/purple/coral tokens match the requested theme. Measured ordinary text/control pairs, including the worst primary-button gradient endpoint, reach at least **6.6955:1**. However, a screenshot-backed check found that the mobile Japanese tagline overlays the decorative lavender arc: **#EAA0B7 over composited #524B6C = 3.9549:1** at 21.6 px / weight 500. It requires **4.5:1**, so mobile text contrast **fails AA** at all four tested phone widths. The desktop hero passes. The first DOM-only scan missed the sibling SVG backdrop; [hero-contrast.json](hero-contrast.json) uses CSS foreground colors and a text-hidden screenshot of the actual background at opaque glyph pixels. The criterion is [WCAG 2.2, 1.4.3](https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html).')
p('Screenshot paths: [iPhone full page](screenshots/iphone-13.png), [iPhone hero](screenshots/iphone-13-hero.png), [Pixel full page](screenshots/pixel-7.png), [Pixel previews](screenshots/pixel-7-previews.png), [360 px](screenshots/phone-360.png), [430 px](screenshots/phone-430.png), [360 px command example](screenshots/phone-360-code.png), [desktop](screenshots/desktop.png). Eight of nine unique external links return HTTP 200; the runtime source link returns HTTP 404 ([links.json](links.json)).')
p('**Defects, minimal reproductions and recommended order.**')
table(['ID / priority','Minimal reproduction and observed result','Likely code / first fix'],[
['D1 / first, parity','Run `node --import tsx tests/browser/diagnostics.mts wasm replay`; Catch grid max/median 2.669/1.212 ms, and all four browser-PCM replays diverge. `wasm control` passes all four.','`packages/runtime/src/decode_audio.ts:7–21`; standardize decoder clipping, downmix, resampling and normalization with Python before claiming browser frontend parity.'],
['D2 / recovery','Run `node tests/browser/fallback.mjs`; device-creation failure gives `Could not load the model: 9392000`, with no WASM retry. Missing-adapter case succeeds.','`site/worker.ts:64–76`, `src/models.ts:94–98`; retry whole-model initialization on WASM after GPU initialization fails, dispose partial sessions, and show a useful error. [Screenshot](screenshots/fallback-device-failure.png).'],
['D3 / mobile AA','Open at 390 px (also 360/393/430); Japanese tagline crosses the arc, contrast 3.955:1 instead of 4.5:1.','`public/styles.css:89,92,240` `.hero-arcs` / `.hero .jp`; move or fade the decorative arc behind the tagline, or give the text a sufficiently dark backing.'],
['D4 / link','Click `@ensomi/runtime` under “Run it yourself”; GitHub returns 404 at `ensomi-web/tree/main/packages/runtime`.','`public/index.html:251`; point to a published revision, or verify the destination after the runtime branch lands on main.'],
['D5 / strict mobile no-scroll target','At 360 px, scroll to “Run it yourself”: the command box is 326 px wide with 650 px of content and requires horizontal panning.','`public/styles.css:226` `pre` and `public/index.html:253`; wrap/split commands on narrow screens. Page-wide overflow itself passes.']])
p('Fix **D1 first** if browser/Python replay parity is the release gate. D2 and D3 should also be fixed before treating the page as broadly robust and AA compliant. Then repair the link and narrow-screen command layout. Provider selection per graph is the next performance experiment: keep BeatThis on WebGPU and benchmark rows/R2 steps on WASM; the present small-step GPU transfers cost substantially more than CPU execution. Also benchmark parallel loading or packing of the ten initial-state files currently awaited serially in `src/r2/stepper.ts:7–8`; their cold network latency appears inside R2 time. No performance change was made in this task.')
p('Reusable commands and measurement caveats are in [tests/browser/README.md](../../tests/browser/README.md). Only test scripts and evidence were added under the authorized directories; product source was not edited. Raw tensors were served read-only from the existing reference directory; generated bundles, archives, long logs, and frame traces are under `bulk/`.')
(root/'report.md').write_text('\n'.join(parts))
print('Wrote',root/'report.md')
